from typing import Dict, List, Optional, Tuple
from collections import Counter, OrderedDict, defaultdict, deque
import heapq

def simplify_path(path: str) -> str:
    stack: list[str] = []
    for token in path.split("/"):
        if token in {"", "."}:
            continue
        if token == "..":
            if stack:
                stack.pop()
        else:
            stack.append(token)
    return "/" + "/".join(stack)
